+	tcphdrlen = tmptcphdr.th_off * 4;
+	if (tcphdrlen <= 20 || tcphdrlen < (unsigned int)tcpsize) {
+		printf("  TCP timestamp echo: option STRIPPED "
+		       "(no TCP options in reply)\n\n");
+		return;
