+	CHECK(tcp_tsecr_check(htonl(11)) == 1,
+	      "recent entries remain in the ring buffer");
+	CHECK(tcp_tsecr_check(htonl(TCP_TS_HISTORY_SIZE + 10)) == 1,
+	      "newest entry is verifiable");
